async function runScreenwritingAgent(nodeId, opts={}){
    const node = nodes.find(n => n.id === nodeId);
    if(!node || node.type !== 'screenwritingAgent' || isNodeDisabled(node)) return;
    const brief = String(node.brief || '').trim();
    const material = String(node.material || '').trim();
    if(brief.length < 8 && material.length < 8){
        const msg = langIsEn()
            ? 'Provide a brief or material (≥8 chars).'
            : '请提供 brief 或素材（至少 8 字）。';
        node.runStatus = 'failed';
        node.runError = msg;
        refreshNodes([nodeId]);
        return;
    }
    if(!opts.cascade){
        node.runStatus = 'running';
        node.runError = '';
        node.running = true;
        refreshNodes([nodeId]);
    }
    setStatus(langIsEn() ? 'Screenwriting Agent: writing…' : '编剧 Agent：正在创作…');
    const execute = async () => {
    try {
        const res = await apiFetch('/api/canvas/screenwriting', {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({
                mode:normalizeScreenwritingMode(node.mode),
                brief,
                material,
                durationHint:String(node.durationHint || '').trim(),
                model:clampAgentTextModel(node.model),
            }),
        });
        if(!res.ok) throw new Error(await responseErrorMessage(res, langIsEn() ? 'Screenwriting failed' : '编剧生成失败'));
        const data = await res.json();
        const markdown = String(data.markdown || data.display_text || '').trim();
        if(!markdown) throw new Error(langIsEn() ? 'Empty screenwriting output' : '编剧输出为空');
        node.outputData = data;
        node.outputText = markdown;
        if(data.mode) node.mode = normalizeScreenwritingMode(data.mode);
        const view = syncScreenwritingToTextOutput(node, data);
        if(!opts.cascade) node.running = false;
        node.runStatus = 'done';
        node.runError = '';
        const refreshIds = [nodeId];
        if(view) refreshIds.push(view.id);
        refreshNodes(refreshIds);
        setStatus(langIsEn() ? 'Screenwriting ready — see text output' : '编剧已生成 — 见右侧文本输出');
        scheduleSave();
        if(view){
            requestAnimationFrame(() => {
                document.querySelector(`.node[data-id="${view.id}"]`)?.scrollIntoView?.({block:'nearest', behavior:'smooth'});
            });
        }
    } catch(err) {
        if(!opts.cascade) node.running = false;
        node.runStatus = 'failed';
        node.runError = err.message || String(err);
        refreshNodes([nodeId]);
        if(opts.cascade) throw err;
        scheduleSave();
    }
    };
    if(opts.cascade) await execute();
    else void execute();
}
function pixarAdAgentScript(node){
    const source = orderedSources(node, generatorSources(node)).find(item => item.prompt && !item.refs?.length);
    const upstream = String(source?.prompt || '').trim();
    const inline = String(node.story || node.raw_script || '').trim();
    return upstream && inline ? `${upstream}\n\n${inline}` : (upstream || inline);
}
function storyAnimMissingKinds(node){
    const bindings = mxShellPromptAgentImageBindings(node);
    const kinds = new Set(bindings.map(b => b.kind).filter(k => k && k !== 'auto'));
    const missing = [];
    if(!kinds.has('character') && !bindings.length) missing.push('character');
    if(!kinds.has('prop')) missing.push('prop');
    if(!kinds.has('scene')) missing.push('scene');
    return missing;
}
function renderPixarAdScriptAgentBody(node){
    node.model = clampAgentTextModel(node.model);
    node.durationPreset = normalizeStoryAnimDurationPreset(node.durationPreset, node.durationSec);
    node.durationSec = resolveStoryAnimDurationSec(node);
    if(!node.refNames || typeof node.refNames !== 'object') node.refNames = {};
    if(!node.refKinds || typeof node.refKinds !== 'object') node.refKinds = {};
    const script = pixarAdAgentScript(node);
    const outputText = String(node.outputText || '').trim();
    const imageUrls = mxShellPromptAgentImageUrls(node);
    const missing = storyAnimMissingKinds(node);
    const ready = script.length >= 20;
    const wrap = document.createElement('div');
    wrap.className = 'generator-body pixar-ad-script-body agent-console-body agent-h-body';
    const priorAssets = collectStoryAnimPriorAssetPrompts(node);
    const flowHint = langIsEn()
        ? `Flow: ① asset prompts → gen images (done) ② story script (locks to ${priorAssets.length ? priorAssets.length + ' asset prompts' : 'story keywords if no assets yet'}) ③ sketch + assets → image gen`
        : `推荐：①资产提示词→手连生图（结束）②分镜脚本${priorAssets.length ? `（已锁定 ${priorAssets.length} 条资产造型）` : '（尚未生成资产提示词时可先写造型）'}③线稿+资产图一起接生图`;
    wrap.innerHTML = `
        <div class="agent-h-panes">
            <div class="agent-h-col agent-h-col-scroll">
                <div class="agent-status-bar ${ready ? 'ok' : 'warn'}">${escapeHtml([
                    `${node.durationSec}s`,
                    clampAgentTextModel(node.model),
                    outputText ? (langIsEn() ? 'outputs ready' : '已有输出') : (ready ? (langIsEn() ? 'Ready' : '可生成') : (langIsEn() ? 'Need story (≥20 chars)' : '需故事创意（≥20字）')),
                ].join(' · '))}</div>
                <div class="mx-shell-result-compact-hint pixar-flow-hint">${escapeHtml(flowHint)}</div>
                ${outputText ? `
                <div class="mx-shell-result-compact">
                    <div class="mx-shell-result-compact-title">${langIsEn() ? 'Outputs ready' : '输出已生成'}</div>
                    <button type="button" class="gen-btn pixar-focus-assets-btn"><i data-lucide="panel-right" class="w-4 h-4"></i><span>${langIsEn() ? 'Open outputs' : '打开输出节点'}</span></button>
                </div>` : node.runStatus === 'failed' && node.runError ? `
                <div class="mx-shell-result-compact is-error-panel"><div class="mx-shell-result-compact-hint">${escapeHtml(node.runError)}</div></div>` : ''}
                <label class="field">
                    <div class="setting-title">${langIsEn() ? 'Story / idea' : '故事创意 / 剧本'}</div>
                    ${script && !String(node.story || node.raw_script || '').trim() ? `<div class="mx-shell-upstream-preview">${escapeHtml(script.slice(0, 220))}${script.length > 220 ? '…' : ''}</div>` : ''}
                    <textarea class="pixar-raw-script" placeholder="${langIsEn() ? 'Paste the story idea or connect an upstream text node…' : '粘贴故事创意，或连接上游文本节点…'}">${escapeHtml(node.story || node.raw_script || '')}</textarea>
                </label>
                <details class="agent-refs-fold" ${imageUrls.length ? 'open' : ''}>
                    <summary>${langIsEn() ? 'Refs on Agent (optional, not required)' : '连到 Agent 的参考图（可选，不必为出脚本而回连）'}</summary>
                    <div class="mx-shell-ref-list"></div>
                </details>
                ${node.runError && !(node.runStatus === 'failed' && !outputText) ? `<div class="replica-run-error">${escapeHtml(node.runError)}</div>` : ''}
            </div>
            <div class="agent-h-col agent-h-col-right agent-h-col-scroll">
                <div class="agent-console-grid">
                    <label class="field">
                        <div class="setting-title">${langIsEn() ? 'Duration' : '时长'}</div>
                        <select class="select-lite pixar-duration-preset">
                            ${['15','20','25','30'].map(v => `<option value="${v}" ${node.durationPreset === v ? 'selected' : ''}>${v}s</option>`).join('')}
                            <option value="custom" ${node.durationPreset === 'custom' ? 'selected' : ''}>${langIsEn() ? 'Custom (>30s)' : '自定义 (>30s)'}</option>
                        </select>
                    </label>
                    <label class="field pixar-custom-duration-field" style="${node.durationPreset === 'custom' ? '' : 'display:none'}">
                        <div class="setting-title">${langIsEn() ? 'Seconds' : '秒数'}</div>
                        <input class="setting-input pixar-duration-sec" type="number" min="31" max="180" value="${escapeAttr(String(node.durationSec || 45))}">
                    </label>
                </div>
                <label class="field">
                    <div class="setting-title">${langIsEn() ? 'Visual style' : '画面风格基调'}</div>
                    <input class="setting-input pixar-style-description" type="text" maxlength="500" value="${escapeHtml(node.style_description || '')}">
                </label>
                <label class="field">
                    <div class="setting-title">${langIsEn() ? 'Model' : '模型'}</div>
                    <select class="select-lite pixar-text-model">${agentTextModelOptions(resolveBatchPosterChatModel(node))}</select>
                </label>
            </div>
        </div>
        <div class="agent-h-foot">
            <div class="gen-run-row pixar-run-actions">
                <button type="button" class="pixar-action-btn is-secondary pixar-asset-prompt-btn ${node.running ? 'running' : ''}" ${!ready || node.running ? 'disabled' : ''} title="${escapeAttr(missing.length ? (langIsEn() ? 'When assets missing' : '缺彩图资产时用') : (langIsEn() ? 'Regenerate asset prompts' : '可重生成资产提示词'))}"><i data-lucide="image-plus" class="w-3.5 h-3.5"></i><span>${node.running ? (langIsEn() ? 'Working…' : '生成中…') : (langIsEn() ? 'Asset prompts' : '资产提示词')}</span></button>
                <button type="button" class="pixar-action-btn is-primary pixar-run-btn ${node.running ? 'running' : ''}" ${!ready || node.running ? 'disabled' : ''} title="${escapeAttr(langIsEn() ? 'No need to rewire asset images here' : '不必先把资产图连回本节点')}"><i data-lucide="sparkles" class="w-3.5 h-3.5"></i><span>${node.running ? (langIsEn() ? 'Directing…' : '导演生成中…') : (langIsEn() ? 'Story script' : '分镜脚本')}</span></button>
            </div>
        </div>
    `;
    const bindText = (selector, key, max) => {
        const input = wrap.querySelector(selector);
        if(!input) return;
        input.onmousedown = e => e.stopPropagation();
        input.oninput = e => {
            node[key] = String(e.target.value || '').slice(0, max);
            if(key === 'story' || key === 'raw_script'){
                node.story = node[key];
                node.raw_script = node[key];
            }
            scheduleSave();
        };
        if(input.tagName === 'TEXTAREA') bindScrollableText(input);
    };
    bindText('.pixar-style-description', 'style_description', 500);
    bindText('.pixar-raw-script', 'story', 24000);
    const presetSel = wrap.querySelector('.pixar-duration-preset');
    presetSel.onmousedown = e => e.stopPropagation();
    presetSel.onchange = e => {
        node.durationPreset = normalizeStoryAnimDurationPreset(e.target.value, node.durationSec);
        node.durationSec = resolveStoryAnimDurationSec(node);
        scheduleSave();
        refreshNodes([node.id]);
    };
    const durInput = wrap.querySelector('.pixar-duration-sec');
    if(durInput){
        durInput.onmousedown = e => e.stopPropagation();
        durInput.oninput = e => {
            node.durationPreset = 'custom';
            node.durationSec = Math.min(180, Math.max(31, Math.round(Number(e.target.value) || 45)));
            scheduleSave();
        };
    }
    const modelSelect = wrap.querySelector('.pixar-text-model');
    modelSelect.onmousedown = e => e.stopPropagation();
    modelSelect.onchange = e => {
        node.model = clampAgentTextModel(e.target.value);
        scheduleSave();
        refreshNodes([node.id]);
    };
    const focusBtn = wrap.querySelector('.pixar-focus-assets-btn');
    if(focusBtn){
        focusBtn.onclick = e => {
            e.stopPropagation();
            const outputs = syncPixarAdAssetsToTextOutputs(node, node.outputData || {});
            if(!outputs.length) return;
            selected.clear();
            selected.add(outputs[0].id);
            refreshNodes([node.id, ...outputs.map(out => out.id)]);
            scheduleSave();
            requestAnimationFrame(() => document.querySelector(`.node[data-id="${outputs[0].id}"]`)?.scrollIntoView?.({block:'nearest', behavior:'smooth'}));
        };
    }
    wrap.querySelector('.pixar-asset-prompt-btn').onclick = e => {
        e.stopPropagation();
        void runPixarAdScriptAgent(node.id, {mode:'asset_prompts'});
    };
    wrap.querySelector('.pixar-run-btn').onclick = e => {
        e.stopPropagation();
        void runPixarAdScriptAgent(node.id, {mode:'story_script'});
    };
    renderMxShellRefList(wrap.querySelector('.mx-shell-ref-list'), node, langIsEn()
        ? 'Optional vision boost only. Prefer wiring assets to the image gen node with sketch prompts.'
        : '仅可选视觉增强。更推荐：资产图与线稿提示词一起接到生图节点，不必回连本 Agent。');
    return wrap;
}
async function runPixarAdScriptAgent(nodeId, opts={}){
    const node = nodes.find(n => n.id === nodeId);
    if(!node || node.type !== 'pixarAdScriptAgent' || isNodeDisabled(node)) return;
    const mode = String(opts.mode || 'story_script') === 'asset_prompts' ? 'asset_prompts' : 'story_script';
    const story = pixarAdAgentScript(node);
    if(story.length < 20){
        node.runStatus = 'failed';
        node.runError = langIsEn() ? 'Please provide a story of at least 20 characters.' : '请提供至少 20 字的故事创意或剧本。';
        refreshNodes([nodeId]);
        return;
    }
    node.durationPreset = normalizeStoryAnimDurationPreset(node.durationPreset, node.durationSec);
    const durationSec = resolveStoryAnimDurationSec(node);
    node.durationSec = durationSec;
    if(!opts.cascade){
        node.running = true;
        node.runStatus = 'running';
        node.runError = '';
        refreshNodes([nodeId]);
    }
    setStatus(mode === 'asset_prompts'
        ? (langIsEn() ? 'Story Anim Agent: asset prompts…' : '故事动画分镜 Agent：正在生成资产提示词…')
        : (langIsEn() ? 'Story Anim Agent: storyboard script…' : '故事动画分镜 Agent：正在生成分镜脚本…'));
    const execute = async () => {
        try {
            const bindings = mxShellPromptAgentImageBindings(node);
            const resolvedUrls = [];
            const resolvedBindings = [];
            for(const binding of bindings){
                const url = await resolveMxShellImageUrlForApi(binding.url);
                if(!url) continue;
                resolvedUrls.push(url);
                resolvedBindings.push({index:resolvedUrls.length, name:binding.name, kind:binding.kind});
            }
            const missing = storyAnimMissingKinds(node);
            const priorAssetPrompts = mode === 'story_script' ? collectStoryAnimPriorAssetPrompts(node) : [];
            const res = await apiFetch('/api/canvas/story-anim-script', {
                method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({
                    mode,
                    story,
                    raw_script:story,
                    durationSec,
                    duration_sec:durationSec,
                    style_description:String(node.style_description || '').trim(),
                    model:clampAgentTextModel(node.model),
                    imageUrls:resolvedUrls,
                    imageBindings:resolvedBindings,
                    missing_kinds: mode === 'asset_prompts' ? (missing.length ? missing : ['character','prop','scene']) : undefined,
                    asset_prompts: priorAssetPrompts.length ? priorAssetPrompts : undefined,
                    prior_asset_prompts: priorAssetPrompts.length ? priorAssetPrompts : undefined,
                }),
            });
            if(!res.ok) throw new Error(await responseErrorMessage(res, langIsEn() ? 'Story animation script failed' : '故事动画脚本生成失败'));
            const data = await res.json();
            const displayText = String(data.display_text || '').trim();
            if(!displayText) throw new Error(langIsEn() ? 'Empty response' : '输出为空');
            if(mode === 'story_script' && (!data.storyboard_table_md || !(data.sketch_sheets?.length || data.sketch_prompts))){
                throw new Error(langIsEn() ? 'Incomplete storyboard response' : '分镜脚本输出不完整');
            }
            if(mode === 'asset_prompts' && !(data.asset_prompts?.length)){
                throw new Error(langIsEn() ? 'No asset prompts returned' : '未返回资产提示词');
            }
            if(mode === 'asset_prompts'){
                node.lastAssetPrompts = Array.isArray(data.asset_prompts) ? data.asset_prompts : [];
                node.outputData = {...(node.outputData && typeof node.outputData === 'object' ? node.outputData : {}), ...data, asset_prompts:node.lastAssetPrompts};
            } else {
                node.outputData = {
                    ...data,
                    asset_prompts: priorAssetPrompts.length ? priorAssetPrompts : (node.lastAssetPrompts || []),
                };
            }
            node.outputText = displayText;
            const outputs = syncPixarAdAssetsToTextOutputs(node, data);
            if(!opts.cascade) node.running = false;
            node.runStatus = 'done';
            node.runError = '';
            refreshNodes([nodeId, ...outputs.map(out => out.id)]);
            scheduleSave();
            setStatus(mode === 'asset_prompts'
                ? (langIsEn() ? `Asset prompts ready — ${outputs.length} outputs` : `资产提示词已生成 — ${outputs.length} 个输出`)
                : (langIsEn() ? 'Story script ready — outputs created' : '分镜脚本已生成 — 已分流输出节点'));
            if(outputs[0]) requestAnimationFrame(() => document.querySelector(`.node[data-id="${outputs[0].id}"]`)?.scrollIntoView?.({block:'nearest', behavior:'smooth'}));
        } catch(err) {
            if(!opts.cascade) node.running = false;
            node.runStatus = 'failed';
            node.runError = err.message || String(err);
            refreshNodes([nodeId]);
            scheduleSave();
            if(opts.cascade) throw err;
        }
    };
    if(opts.cascade) await execute();
    else void execute();
}

function runScreenwritingFromButton(nodeId, event){
    event?.preventDefault?.();
    event?.stopPropagation?.();
    void runScreenwritingAgent(nodeId);
}
window.runScreenwritingFromButton = runScreenwritingFromButton;

function replicaAgentUpstreamImages(node, ctx=loopContext){
    if(!node || node.type !== 'replicaAgent') return [];
    return orderedSources(node, generatorSources(node, ctx))
        .filter(s => s.refs?.length)
        .flatMap(s => s.refs.map((ref, i) => {
            const url = ref.url || '';
            const kind = ref.kind || 'image';
            if(!url || kind !== 'image') return null;
            return {
                id:s.refs.length > 1 ? `${s.id}:ref:${i}:${url}` : s.id,
                type:'image',
                url,
                name:ref.name || outputImageName(url),
                mediaKind:'image',
                role:ref.role || '',
            };
        }))
        .filter(Boolean);
}
function isReplicaBackgroundSourceId(sourceId){
    const id = String(sourceId || '');
    return id.includes(':image:') || id.includes(':img:') || id.includes(':generated:') || id.includes(':batch-image') || id.includes(':group-');
}
function isReplicaDirectImageSource(img){
    const n = nodes.find(x => x.id === img?.id);
    return isNodeEnabled(n) && n?.type === 'image' && Boolean(img?.url);
}
function normalizeReplicaCharacterRefUrls(node){
    if(!Array.isArray(node?.replica_character_ref_urls)) return [];
    return [...new Set(node.replica_character_ref_urls.map(u => String(u || '').trim()).filter(Boolean))];
}
function syncReplicaAgentRoles(node){
    if(!node || node.type !== 'replicaAgent') return;
    if(!node.roles || typeof node.roles !== 'object') node.roles = {};
    const images = replicaAgentUpstreamImages(node);
    const ids = new Set(images.map(img => img.id));
    Object.keys(node.roles).forEach(id => {
        if(!ids.has(id)) delete node.roles[id];
    });
    // 生成器/输出帧等：默认构图参考
    images.filter(img => isReplicaBackgroundSourceId(img.id)).forEach(img => {
        if(node.roles[img.id] !== 'character') node.roles[img.id] = 'background';
    });
    const directImages = images.filter(isReplicaDirectImageSource);
    const explicitBackground = directImages.find(img => node.roles[img.id] === 'background');
    if(directImages.length >= 2){
        const bg = explicitBackground || directImages[0];
        node.roles[bg.id] = 'background';
        directImages.forEach(img => {
            if(img.id === bg.id) return;
            if(node.roles[img.id] !== 'background') node.roles[img.id] = 'character';
        });
    } else if(directImages.length === 1){
        if(node.roles[directImages[0].id] !== 'character') node.roles[directImages[0].id] = 'background';
    }
    images.forEach(img => {
        if(!['background','character'].includes(node.roles[img.id])) node.roles[img.id] = 'background';
    });
    let backgrounds = images.filter(img => node.roles[img.id] === 'background');
    if(images.length > 1 && !backgrounds.length){
        const fallback = images.find(img => isReplicaBackgroundSourceId(img.id)) || directImages[0] || images[0];
        if(fallback) node.roles[fallback.id] = 'background';
        backgrounds = images.filter(img => node.roles[img.id] === 'background');
    }
    if(backgrounds.length > 1){
        const keep = backgrounds[0];
        backgrounds.slice(1).forEach(img => {
            if(img.id === keep.id) return;
            node.roles[img.id] = 'character';
        });
    }
    node.replica_character_ref_urls = images
        .filter(img => node.roles[img.id] === 'character')
        .map(img => String(img.url || '').trim())
        .filter(Boolean);
}
function updateReplicaAgentStatusBadges(nodeEl, node){
    if(!nodeEl || !node || node.type !== 'replicaAgent') return;
    syncReplicaAgentRoles(node);
    const {background, characters} = replicaAgentRoleImages(node);
    const bgOk = Boolean(background?.url);
    const charCount = characters.length;
    const charOk = charCount > 0;
    const badges = nodeEl.querySelectorAll('.replica-status-badge');
    if(badges[0]){
        badges[0].classList.toggle('ok', bgOk);
        badges[0].classList.toggle('warn', !bgOk);
        const span = badges[0].querySelector('span');
        if(span){
            span.textContent = bgOk
                ? (langIsEn() ? 'Background ready (图1)' : '已连接背景/构图参考（图1）')
                : (langIsEn() ? 'Connect background (图1)' : '请连接背景/构图参考（图1）');
        }
    }
    if(badges[1]){
        badges[1].classList.toggle('ok', charOk);
        badges[1].classList.toggle('neutral', !charOk);
        const span = badges[1].querySelector('span');
        if(span){
            span.textContent = charOk
                ? (langIsEn() ? `${charCount} character ref(s) ready` : `已连接 ${charCount} 张角色参考`)
                : (langIsEn() ? 'Character ref optional' : '角色参考可选');
        }
    }
}
