/** 用户展开或批量生图主动打开时用网格；叠卡收起时角标可再展开看进度 */
function genStageShowsGrid(node, urls, pendings){
    if(!node?.historyOpen) return false;
    const list = urls || [];
    const waiting = pendings || [];
    if(waiting.length > 0) return true;
    // 图片组批量：任务创建前已有进度标记，先出网格避免闪一下叠卡
    if(node._batchProgress) return true;
    return list.length > 1;
}
function renderGenStageStackHtml(node, urls, primary, busyOverlay, pendingCount = 0){
    const count = urls.length;
    const waiting = Math.max(0, Number(pendingCount) || 0);
    // 背后最多 3 层：用其他结果缩略图做出扇叠，让人一眼知道「这里不止一张」
    const peeks = urls.filter(u => u !== primary).slice(-3);
    const peekHtml = peeks.map((url, i) => {
        const depth = peeks.length - i;
        return `<div class="gen-stage-stack-peek" style="--peek:${depth}" aria-hidden="true">${genStageThumbHtml(url)}</div>`;
    }).join('');
    const ar = genStageAspectCssForUrl(node, primary) || genStageTileAspectCss(node);
    // 视频结果用量词「条」；图片仍用「张」
    const unitZh = node?.type === 'video' ? '条' : '张';
    const expandTitle = waiting
        ? (langIsEn()
            ? `Expand · ${count} ready, ${waiting} generating`
            : `展开 · ${count} ${unitZh}已出 · ${waiting} ${unitZh}生成中`)
        : (langIsEn() ? `View all ${count} results` : `展开查看全部 ${count} ${unitZh}`);
    const totalShown = count + waiting;
    const badgeText = waiting
        ? (langIsEn() ? `${count}+${waiting}` : `${count}+${waiting}${unitZh}`)
        : (langIsEn() ? `${count}` : `${count}${unitZh}`);
    const busyClass = waiting || busyOverlay ? ' is-busy' : '';
    const peekN = Math.min(3, Math.max(0, totalShown - 1));
    const refPickClass = isGenRefPicking(node) ? ' is-ref-picking' : '';
    const refPickOverlay = isGenRefPicking(node)
        ? `<div class="gen-stage-ref-pick-dim" aria-live="polite"><span class="gen-stage-ref-pick-exit">${escapeHtml(langIsEn() ? 'esc Exit' : 'esc 退出')}</span></div>`
        : '';
    return `<div class="gen-stage has-images is-stack${busyClass}${refPickClass}" style="--stack-peeks:${peekN}">
        <div class="gen-stage-frame is-stack">
            <div class="gen-stage-stack">
                ${peekHtml}
                <div class="gen-stage-stack-hero" data-preview-url="${escapeAttr(primary)}" role="img" style="--gen-tile-ar:${ar}">
                    ${genStageHeroMediaHtml(node, primary)}
                    <button type="button" class="gen-stage-stack-expand" data-action="expand-grid" title="${escapeAttr(expandTitle)}">
                        <i data-lucide="maximize-2" class="w-6 h-6"></i>
                        <span>${escapeHtml(badgeText)}</span>
                    </button>
                    ${busyOverlay}
                </div>
            </div>
            ${refPickOverlay}
        </div>
    </div>`;
}
function renderGenStageHtml(node){
    if(isGenConsoleNode(node) && Array.isArray(node.history) && node.history.length > MAX_GEN_HISTORY){
        node.history = node.history.slice(-MAX_GEN_HISTORY);
        syncGeneratorPreviewFromHistory(node);
    }
    if(isGenConsoleNode(node) && Array.isArray(node.previewRoundUrls) && node.previewRoundUrls.length > MAX_GEN_PREVIEW){
        node.previewRoundUrls = node.previewRoundUrls.slice(-MAX_GEN_PREVIEW);
    }
    const urls = generatorPreviewUrls(node);
    const pendings = generatorPendingList(node);
    const pendingN = pendings.length || agentPendingCount(node.id);
    const isBusy = pendingN > 0 || Boolean(node.running) || node.runStatus === 'running' || node.runStatus === 'queued';
    const showGrid = genStageShowsGrid(node, urls, pendings);
    // 网格内已有 pending 占位时，不再盖整层半透明蒙层（会把已出图变灰）
    const busyLabel = node._batchProgress
        ? (langIsEn() ? `Generating ${node._batchProgress}…` : `生成中 ${node._batchProgress}…`)
        : (pendingN > 1
            ? (langIsEn() ? `Generating (${pendingN})…` : `生成中 (${pendingN})…`)
            : (langIsEn() ? 'Generating…' : '生成中…'));
    // 收起态：主图模糊 + 选参考同款白流光（左→右扫边）+ 底部状态条
    const busyOverlay = (isBusy && !showGrid)
        ? `<div class="gen-stage-busy gen-stage-busy-collapsed" aria-live="polite">
            <div class="gen-stage-busy-flow-bloom" aria-hidden="true"></div>
            <div class="gen-stage-busy-flow" aria-hidden="true"></div>
            <div class="gen-stage-busy-bar">
                <span class="gen-stage-busy-dot" aria-hidden="true"></span>
                <span class="gen-stage-busy-label">${escapeHtml(busyLabel)}</span>
            </div>
        </div>`
        : '';
    const emptyIcon = node.type === 'video' ? 'clapperboard' : 'image';
    const refPickClass = isGenRefPicking(node) ? ' is-ref-picking' : '';
    const refPickOverlay = isGenRefPicking(node)
        ? `<div class="gen-stage-ref-pick-dim" aria-live="polite"><span class="gen-stage-ref-pick-exit">${escapeHtml(langIsEn() ? 'esc Exit' : 'esc 退出')}</span></div>`
        : '';
    if(urls.length) ensureGeneratorPrimaryAtAnchor(node);
    if(showGrid){
        const list = generatorPreviewUrls(node);
        const primary = list.length
            ? (genStageCollapsedDisplayUrl(node, list) || list[Math.max(0, Math.min(list.length - 1, Number(node.previewIndex ?? 0)))])
            : '';
        const pendingById = new Map(pendings.map(p => [String(p.id), p]));
        const slots = Array.isArray(node._stageSlots) && node._stageSlots.length
            ? node._stageSlots
            : [
                ...list.map(url => ({ kind: 'url', url })),
                ...pendings.map(p => ({ kind: 'pending', id: p.id })),
            ];
        let readyIdx = 0;
        let pendingIdx = 0;
        const tiles = slots.map((slot) => {
            if(slot?.kind === 'pending'){
                const p = pendingById.get(String(slot.id)) || { id: slot.id, aspect: slot.aspect };
                if(!p.aspect && slot.aspect) p.aspect = slot.aspect;
                const html = renderGenStagePendingTileHtml(p, pendingIdx, node);
                pendingIdx += 1;
                return html;
            }
            const url = outputUrlValue(slot?.url || slot);
            if(!url) return '';
            const html = renderGenStageTileHtml(node, url, readyIdx, primary);
            readyIdx += 1;
            return html;
        }).join('');
        // 槽位里没有、但仍在 pending 列表的（异常兜底）附在末尾
        const slottedPending = new Set(
            slots.filter(s => s?.kind === 'pending').map(s => String(s.id))
        );
        const orphanPending = pendings
            .filter(p => !slottedPending.has(String(p.id)))
            .map((p, i) => renderGenStagePendingTileHtml(p, pendingIdx + i, node))
            .join('');
        const total = Math.max(1, slots.length + (orphanPending ? pendings.filter(p => !slottedPending.has(String(p.id))).length : 0));
        const cols = genStageGridCols(total, node);
        // 不再挂「收起」胶囊：点画布空白 / 设为主图即可回叠卡，避免盖住图左上角说明
        return `<div class="gen-stage has-images history-open is-grid ${isBusy ? 'is-busy' : ''}${isGenBatchPicking(node) ? ' is-batch-picking' : ''}${refPickClass}">
            <div class="gen-stage-frame is-grid" style="--gen-grid-cols:${cols}">
                <div class="gen-stage-grid" role="listbox">${tiles}${orphanPending}</div>
                ${refPickOverlay}
            </div>
        </div>`;
    }
    if(!urls.length){
        const ar = genStageTileAspectCss(node);
        return `<div class="gen-stage is-empty ${isBusy ? 'is-busy' : ''}${refPickClass}">
            <div class="gen-stage-frame" style="aspect-ratio:${ar}">
                <div class="gen-stage-empty"><i data-lucide="${emptyIcon}" class="w-10 h-10"></i></div>
                ${busyOverlay}
                ${refPickOverlay}
            </div>
        </div>`;
    }
    clampGeneratorPreviewIndex(node);
    // ensure/clamp 可能改过 previewRoundUrls，封面必须用最新列表
    const coverUrls = generatorPreviewUrls(node);
    const primary = genStageCollapsedDisplayUrl(node, coverUrls);
    // 多图，或单图但有在途任务：叠卡/单卡 + 角标（生成中可展开看进度）
    if(coverUrls.length > 1 || pendings.length > 0){
        return renderGenStageStackHtml(node, coverUrls, primary, busyOverlay, pendings.length);
    }
    return `<div class="gen-stage has-images ${isBusy ? 'is-busy' : ''}${refPickClass}">
        <div class="gen-stage-frame">
            <div class="gen-stage-hero" data-preview-url="${escapeAttr(primary)}" role="img">
                ${genStageHeroMediaHtml(node, primary)}
            </div>
            ${busyOverlay}
            ${refPickOverlay}
        </div>
    </div>`;
}
const GEN_STAGE_FLIP_MS = 420;
const GEN_STAGE_FLIP_EASE = 'cubic-bezier(.22,.61,.36,1)';
function prefersGenStageReducedMotion(){
    try{ return window.matchMedia('(prefers-reduced-motion: reduce)').matches; }
    catch(_){ return false; }
}
function captureGenStageFlipMap(stage){
    const map = new Map();
    if(!stage) return map;
    const add = (el, url) => {
        const key = outputUrlValue(url);
        if(!key || map.has(key)) return;
        const r = el.getBoundingClientRect();
        if(r.width < 2 || r.height < 2) return;
        map.set(key, {left:r.left, top:r.top, width:r.width, height:r.height, el});
    };
    stage.querySelectorAll('.gen-stage-stack-hero[data-preview-url], .gen-stage-tile[data-preview-url], .gen-stage-hero[data-preview-url]').forEach(el => {
        add(el, el.getAttribute('data-preview-url'));
    });
    stage.querySelectorAll('.gen-stage-stack-peek').forEach(el => {
        const media = el.querySelector('img[src], video[src]');
        if(media) add(el, media.getAttribute('src'));
    });
    return map;
}
function waitGenStageMediaReady(stage){
    if(!stage) return Promise.resolve();
    const medias = [...stage.querySelectorAll('.gen-stage-tile-media img, .gen-stage-tile-media video, .gen-stage-stack-hero img, .gen-stage-stack-hero video, .gen-stage-hero img, .gen-stage-hero video')];
    return Promise.all(medias.map(media => {
        if(media.tagName === 'VIDEO'){
            if(media.readyState >= 1) return Promise.resolve();
            return new Promise(resolve => {
                media.addEventListener('loadedmetadata', resolve, {once:true});
                media.addEventListener('error', resolve, {once:true});
            });
        }
        if(media.complete && media.naturalWidth > 0){
            return media.decode ? media.decode().catch(() => {}) : Promise.resolve();
        }
        return new Promise(resolve => {
            const done = () => {
                if(media.decode) media.decode().then(resolve, resolve);
                else resolve();
            };
            media.addEventListener('load', done, {once:true});
            media.addEventListener('error', resolve, {once:true});
        });
    })).then(() => {});
}
/** 翻牌幽灵媒体：视频优先截当前帧成图（对齐图片「已解码像素飞」），避免黑帧/等 metadata */
function mediaSnapshotForFlipGhost(srcMedia, url){
    const fit = 'width:100%;height:100%;object-fit:cover;display:block';
    if(srcMedia?.tagName === 'VIDEO'){
        try {
            if(srcMedia.videoWidth > 0 && srcMedia.readyState >= 2){
                const c = document.createElement('canvas');
                c.width = srcMedia.videoWidth;
                c.height = srcMedia.videoHeight;
                const ctx = c.getContext('2d');
                if(ctx){
                    ctx.drawImage(srcMedia, 0, 0);
                    const img = document.createElement('img');
                    img.src = c.toDataURL('image/jpeg', 0.92);
                    img.alt = '';
                    img.draggable = false;
                    img.style.cssText = fit;
                    return img;
                }
            }
        } catch(_){ /* 跨域污染等：退回 clone */ }
        const clone = srcMedia.cloneNode(true);
        clone.removeAttribute('style');
        clone.style.cssText = fit;
        clone.muted = true;
        clone.playsInline = true;
        clone.preload = 'metadata';
        clone.draggable = false;
        try { clone.currentTime = Number(srcMedia.currentTime) || 0; } catch(_){ /* ignore */ }
        return clone;
    }
    if(srcMedia?.tagName === 'IMG'){
        const clone = srcMedia.cloneNode(true);
        clone.removeAttribute('style');
        clone.style.cssText = fit;
        clone.draggable = false;
        return clone;
    }
    if(isVideoUrl(url)){
        const v = document.createElement('video');
        v.src = url;
        v.muted = true;
        v.playsInline = true;
        v.preload = 'metadata';
        v.style.cssText = fit;
        return v;
    }
    const img = document.createElement('img');
    img.src = url;
    img.alt = '';
    img.draggable = false;
    img.style.cssText = fit;
    return img;
}
/** 在拆 DOM 之前盖住旧图：克隆已解码媒体，避免「先空一帧再飞」 */
function spawnGenStageFlipGhostFromCapture(from, url){
    const ghost = document.createElement('div');
    ghost.className = 'gen-stage-flip-ghost';
    const key = outputUrlValue(url) || String(url || '');
    ghost.dataset.flipUrl = key;
    ghost.style.left = `${from.left}px`;
    ghost.style.top = `${from.top}px`;
    ghost.style.width = `${from.width}px`;
    ghost.style.height = `${from.height}px`;
    ghost.style.opacity = '1';
    ghost.style.transition = 'none';
    const srcMedia = from.el?.querySelector?.('img, video, .gen-stage-video-el') || null;
    const srcUrl = outputUrlValue(srcMedia?.getAttribute?.('src') || srcMedia?.currentSrc || '');
    // 只有同源才用现场像素，避免「从封面飞出却带着封面、落地换成别的」再闪一下
    if(srcMedia && srcUrl && srcUrl === key){
        ghost.appendChild(mediaSnapshotForFlipGhost(srcMedia, key));
    } else {
        ghost.appendChild(mediaSnapshotForFlipGhost(null, key));
    }
    document.body.appendChild(ghost);
    return ghost;
}
function animateGenStageFlipGhostTo(ghost, to, {fadeOut=false, delay=0, scaleTo=1}={}){
    if(!ghost || !to) return;
    // 先读布局再开 transition，避免第一帧就飞到终点
    void ghost.offsetWidth;
    ghost.style.transformOrigin = 'center center';
    ghost.style.transition = [
        `left ${GEN_STAGE_FLIP_MS}ms ${GEN_STAGE_FLIP_EASE} ${delay}ms`,
        `top ${GEN_STAGE_FLIP_MS}ms ${GEN_STAGE_FLIP_EASE} ${delay}ms`,
        `width ${GEN_STAGE_FLIP_MS}ms ${GEN_STAGE_FLIP_EASE} ${delay}ms`,
        `height ${GEN_STAGE_FLIP_MS}ms ${GEN_STAGE_FLIP_EASE} ${delay}ms`,
        `opacity ${Math.round(GEN_STAGE_FLIP_MS * .55)}ms ease ${delay}ms`,
        `transform ${GEN_STAGE_FLIP_MS}ms ${GEN_STAGE_FLIP_EASE} ${delay}ms`
    ].join(', ');
    requestAnimationFrame(() => {
        ghost.style.left = `${to.left}px`;
        ghost.style.top = `${to.top}px`;
        ghost.style.width = `${to.width}px`;
        ghost.style.height = `${to.height}px`;
        if(scaleTo !== 1) ghost.style.transform = `scale(${scaleTo})`;
        if(fadeOut) ghost.style.opacity = '0';
    });
}
function playGenStageFlipMorph(stage, firstMap, ghosts, {expanding=true, node=null, nodeEl=null}={}){
    if(!stage || !firstMap?.size) return;
    const lastMap = captureGenStageFlipMap(stage);
    const hideEls = [...stage.querySelectorAll('.gen-stage-stack-hero, .gen-stage-stack-peek, .gen-stage-tile, .gen-stage-hero, .gen-stage-grid-collapse, .gen-stage-stack-expand')];
    const peekEls = [...stage.querySelectorAll('.gen-stage-stack-peek')];
    hideEls.forEach(el => {
        el.style.opacity = '0';
        el.style.transition = 'none';
    });
    stage.classList.add('is-flipping');
    if(node) node._stageFlipping = true;
    const anchor = [...firstMap.values()][0] || [...lastMap.values()][0];
    const heroEl = stage.querySelector('.gen-stage-stack-hero[data-preview-url], .gen-stage-tile.is-primary[data-preview-url], .gen-stage-hero[data-preview-url]');
    const heroKey = outputUrlValue(heroEl?.getAttribute('data-preview-url') || '');
    // 收起终点只用封面矩形：若飞向带 rotate 的 peek AABB，落地再换成真叠卡会像「刻意对齐」
    const heroLast = (heroKey && lastMap.get(heroKey))
        || (heroEl ? (() => {
            const r = heroEl.getBoundingClientRect();
            return {left:r.left, top:r.top, width:r.width, height:r.height};
        })() : null)
        || [...lastMap.values()][0]
        || anchor;
    const ghostByUrl = new Map(ghosts.map(g => [outputUrlValue(g.dataset.flipUrl), g]));
    const urls = new Set([...firstMap.keys(), ...lastMap.keys()]);
    let i = 0;
    urls.forEach(url => {
        const key = outputUrlValue(url);
        const first = firstMap.get(url) || firstMap.get(key);
        const last = lastMap.get(url) || lastMap.get(key);
        const delay = Math.min(72, i * 14);
        i += 1;
        let ghost = ghostByUrl.get(key) || ghostByUrl.get(url);
        if(expanding){
            if(!last) return;
            const from = first || anchor;
            if(!from) return;
            if(!ghost){
                ghost = spawnGenStageFlipGhostFromCapture(from, key || url);
                ghosts.push(ghost);
                ghostByUrl.set(outputUrlValue(ghost.dataset.flipUrl), ghost);
            }
            animateGenStageFlipGhostTo(ghost, last, {delay});
            return;
        }
        // 收起：全部收进封面，非封面淡出；扇叠 peek 不参与 FLIP 终点
        if(!first || !heroLast) return;
        if(!ghost){
            ghost = spawnGenStageFlipGhostFromCapture(first, key || url);
            ghosts.push(ghost);
            ghostByUrl.set(outputUrlValue(ghost.dataset.flipUrl), ghost);
        }
        const isHero = key === heroKey || url === heroKey;
        animateGenStageFlipGhostTo(ghost, heroLast, {
            fadeOut: !isHero,
            delay,
            scaleTo: isHero ? 1 : 0.92
        });
    });
    const finish = () => {
        // 封面先上屏；peek 稍后淡入，避免「飞到扇位再咬齐」的对齐感
        hideEls.forEach(el => {
            if(el.classList.contains('gen-stage-stack-peek')) return;
            el.style.transition = 'none';
            el.style.opacity = '1';
        });
        peekEls.forEach(el => {
            el.style.transition = 'none';
            el.style.opacity = '0';
        });
        requestAnimationFrame(() => {
            ghosts.forEach(g => g.remove());
            hideEls.forEach(el => {
                if(el.classList.contains('gen-stage-stack-peek')) return;
                el.style.transition = '';
                el.style.opacity = '';
            });
            peekEls.forEach((el, idx) => {
                el.style.transition = `opacity 180ms ease ${idx * 30}ms`;
                el.style.opacity = '1';
            });
            clearTimeout(stage._flipTimer);
            stage._flipTimer = setTimeout(() => {
                peekEls.forEach(el => { el.style.transition = ''; el.style.opacity = ''; });
                stage.classList.remove('is-flipping');
                if(node) delete node._stageFlipping;
                // 尺寸已在 refresh 时算好，收尾再 fit 会微挪一截，像对齐校正
                try { refreshGeometryAfterLayout(); } catch(_){ /* ignore */ }
                if(node && selected.has(node.id)) positionImageGenDock(node);
                if(node && isGenBatchPicking(node)) syncGenBatchPickBar();
            }, 220);
        });
    };
    const maxDelay = Math.min(72, Math.max(0, (urls.size - 1) * 14));
    const animDone = new Promise(resolve => setTimeout(resolve, GEN_STAGE_FLIP_MS + maxDelay + 24));
    Promise.race([
        Promise.all([animDone, waitGenStageMediaReady(stage)]),
        new Promise(resolve => setTimeout(resolve, GEN_STAGE_FLIP_MS + maxDelay + 320))
    ]).then(finish);
}
/** 叠卡↔网格：铺开 / 叠合；程序化切换可传 animate:false */
function setGenStageHistoryOpen(node, open, opts={}){
    if(!node || !isGenConsoleNode(node)) return false;
    const next = !!open;
    if(!!node.historyOpen === next) return false;
    const animate = opts.animate !== false && !prefersGenStageReducedMotion();
    const nodeEl = nodesEl?.querySelector(`.node[data-id="${CSS.escape(node.id)}"]`);
    const host = nodeEl?.querySelector?.('.gen-stage-slot');
    const stage = host?.querySelector?.('.gen-stage');
    const expanding = next;
    let firstMap = null;
    let ghosts = [];
    if(animate && stage){
        firstMap = captureGenStageFlipMap(stage);
        if(!firstMap.size) firstMap = null;
        else {
            // 根因修复：必须先盖幽灵再拆 DOM。旧逻辑是 innerHTML 拆掉→节点瞬间变宽/变窄→幽灵才出现，中间空一帧必闪。
            firstMap.forEach((rect, url) => {
                ghosts.push(spawnGenStageFlipGhostFromCapture(rect, url));
            });
            // 先于 remount：挡住 natural 比例校正，避免翻牌中途挪格
            node._stageFlipping = true;
            // 旧舞台立刻隐身（幽灵已在上层），避免拆节点时旧图与新布局叠闪
            stage.style.opacity = '0';
            stage.style.pointerEvents = 'none';
        }
    }
    node.historyOpen = next;
    if(nodeEl) refreshGenStage(nodeEl, node, {deferFollowUpFit: !!firstMap});
    else refreshNodes([node.id]);
    if(firstMap && nodeEl){
        const nextStage = nodeEl.querySelector('.gen-stage-slot .gen-stage, .gen-stage');
        if(nextStage) playGenStageFlipMorph(nextStage, firstMap, ghosts, {expanding, node, nodeEl});
        else ghosts.forEach(g => g.remove());
    }
    scheduleSave();
    syncImageGenDock();
    // 展开/收起后立刻同步动作条（展开=卸掉，收起=挂回）
    syncImageActionBar();
    return true;
}
function refreshGenStage(root, node, opts={}){
    const host = root?.querySelector?.('.gen-stage-slot') || (root?.classList?.contains('gen-stage-slot') ? root : null);
    if(!host || !node) return;
    host.innerHTML = renderGenStageHtml(node);
    // 动画前先藏真图与按钮，避免中间闪一帧最终态
    if(opts.deferFollowUpFit){
        host.querySelectorAll('.gen-stage-stack-hero, .gen-stage-stack-peek, .gen-stage-tile, .gen-stage-hero, .gen-stage-grid-collapse, .gen-stage-stack-expand').forEach(el => {
            el.style.opacity = '0';
            el.style.transition = 'none';
        });
        host.querySelector('.gen-stage')?.classList.add('is-flipping');
    }
    bindGenStageInteractions(host, node);
    refreshIcons(host);
    // 叠卡↔网格内容高度/宽度变化，非手改尺寸时重测
    if(!node._userSized) delete node._baseFrameH;
    fitGeneratorNodeHeight(node);
    // 翻牌动画期间勿二次 fit，否则终点格子会挪位，卸幽灵时像「图变了」
    if(opts.deferFollowUpFit) return;
    // 展开后节点变高：下一帧重算端口/连线，保证锚在展开块垂直中心
    requestAnimationFrame(() => {
        if(node._stageFlipping) return;
        fitGeneratorNodeHeight(node);
        try { refreshGeometryAfterLayout(); } catch(_){ /* ignore */ }
        if(selected.has(node.id)) positionImageGenDock(node);
        if(isGenBatchPicking(node)) syncGenBatchPickBar();
    });
}
/** 把图片写入系统剪贴板（优先 PNG）；失败则退回复制 URL */
async function copyImageUrlToClipboard(url){
    const target = String(url || '').trim();
    if(!target) throw new Error(langIsEn() ? 'No image' : '没有图片');
    const res = await fetch(target);
    if(!res.ok) throw new Error(langIsEn() ? 'Fetch image failed' : '读取图片失败');
    const blob = await res.blob();
    if(navigator.clipboard?.write && typeof ClipboardItem !== 'undefined'){
        let itemBlob = blob;
        const type = String(blob.type || 'image/png');
        if(type !== 'image/png'){
            try {
                await navigator.clipboard.write([new ClipboardItem({ [type]: blob })]);
                return;
            } catch(_){
                itemBlob = await blobToPngClipboardBlob(blob);
            }
        }
        await navigator.clipboard.write([new ClipboardItem({ 'image/png': itemBlob })]);
        return;
    }
    await copyTextToClipboard(target);
}
function blobToPngClipboardBlob(blob){
    return new Promise((resolve, reject) => {
        const img = new Image();
        const objectUrl = URL.createObjectURL(blob);
        img.onload = () => {
            try {
                const canvasEl = document.createElement('canvas');
                canvasEl.width = img.naturalWidth || img.width;
                canvasEl.height = img.naturalHeight || img.height;
                const ctx = canvasEl.getContext('2d');
                if(!ctx) throw new Error('canvas');
                ctx.drawImage(img, 0, 0);
                canvasEl.toBlob(png => {
                    URL.revokeObjectURL(objectUrl);
                    if(!png) reject(new Error('png'));
                    else resolve(png);
                }, 'image/png');
            } catch(err) {
                URL.revokeObjectURL(objectUrl);
                reject(err);
            }
        };
        img.onerror = () => {
            URL.revokeObjectURL(objectUrl);
            reject(new Error('image load'));
        };
        img.crossOrigin = 'anonymous';
        img.src = objectUrl;
    });
}
/**
 * 删除其它结果图，台面只留 keepUrl。
 * 必须同步 history / previewRoundUrls / _stageSlots / generatedOutputs，
 * 否则 generatorPreviewUrls 会把旧历史灌回，或展开网格仍读脏 _stageSlots。
 */
function deleteOtherGeneratorPreviews(gen, keepUrl){
    if(!isGenConsoleNode(gen) || !keepUrl) return false;
    const previewBefore = generatorPreviewUrls(gen).map(outputUrlValue).filter(Boolean);
    const keepIdx = genStageFindPreviewIndex(previewBefore, keepUrl);
    if(previewBefore.length < 2 || keepIdx < 0) return false;
    const keep = previewBefore[keepIdx];
    const drop = new Set(previewBefore.filter(u => u !== keep));
    const hist = generatorHistoryItems(gen);
    // 台面只留 keep；历史里本批其它图删除。非本批且不在当前预览窗的旧图也一并清掉，
    // 否则 generatorPreviewUrls 会把它们重新 merge 进叠卡，看起来像「删了没效果」。
    if(hist.length){
        gen.history = hist.filter(item => outputUrlValue(item?.url) === keep);
    } else {
        gen.history = [{url: keep}];
    }
    gen.previewRoundUrls = [keep];
    gen.previewIndex = 0;
    gen.primaryPinned = true;
    gen.primaryUrl = keep;
    gen.historyOpen = false;
    if(Array.isArray(gen.generatedOutputs)){
        gen.generatedOutputs = gen.generatedOutputs
            .map(outputUrlValue)
            .filter(u => u === keep);
    }
    // 必须同步槽位，否则展开网格仍按旧 _stageSlots 画出「已删」的图
    if(Array.isArray(gen._stageSlots)){
        const pendingSlots = gen._stageSlots.filter(s => s?.kind === 'pending');
        const keepSlot = gen._stageSlots.find(s => s?.kind === 'url' && outputUrlValue(s.url) === keep);
        gen._stageSlots = [
            keepSlot ? {...keepSlot, url: keep} : {kind:'url', url: keep},
            ...pendingSlots,
        ];
    }
    ensureGeneratorPrimaryAtAnchor(gen);
    refreshDownstreamGenConsumers(gen.id);
    return drop.size > 0;
}
/** 右键结果图：针对「点中的那张」+ 节点级批处理 */
function placeImageNodeMenuNearPointer(clientX, clientY, menuWidth=240){
    imageNodeMenu.style.visibility = 'hidden';
    imageNodeMenu.classList.add('open');
    const menuHeight = imageNodeMenu.offsetHeight || 300;
    // 优先显示在指针上方，避免被底部 gen-dock 挡住
    let left = Math.max(10, Math.min(window.innerWidth - menuWidth - 10, clientX));
    let top = clientY - menuHeight - 8;
    if(top < 10) top = Math.min(window.innerHeight - menuHeight - 10, clientY + 8);
    top = Math.max(10, Math.min(window.innerHeight - menuHeight - 10, top));
    imageNodeMenu.style.left = `${left}px`;
    imageNodeMenu.style.top = `${top}px`;
    imageNodeMenu.style.visibility = '';
}
function bindGenStageDuplicateMenuAction(nodeId){
    imageNodeMenu.querySelector('[data-gen-duplicate]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        duplicateNodeKeepingUpstream(nodeId);
    });
}
function openGenStageResultMenu(nodeId, clientX, clientY, opts={}){
    const node = nodes.find(n => n.id === nodeId);
    if(!node || !isGenConsoleNode(node)) return;
    const urls = generatorPreviewUrls(node);
    ensureImageNodeMenuOutsideDismiss();
    closeCreateMenu();
    closeLinkCreateMenu();
    const en = langIsEn();
    imageNodeMenu.classList.remove('output-node-menu');
    if(!urls.length){
        imageNodeMenu.innerHTML = `
            <button class="menu-btn" type="button" data-gen-duplicate="1"><i data-lucide="copy-plus" class="w-4 h-4"></i><span>${en ? 'Create copy' : '创建副本'}</span></button>
        `;
        placeImageNodeMenuNearPointer(clientX, clientY);
        bindGenStageDuplicateMenuAction(nodeId);
        refreshIcons();
        return;
    }
    let url = String(opts.url || '').trim();
    let previewIndex = Number(opts.previewIndex);
    // 与 deleteOther / 设为主图同一套定位，避免 includes 严格匹配失败后误绑错图或删失败
    let resolvedIdx = url ? genStageFindPreviewIndex(urls, url) : -1;
    if(resolvedIdx < 0){
        if(Number.isFinite(previewIndex) && previewIndex >= 0 && previewIndex < urls.length){
            resolvedIdx = previewIndex;
        } else {
            resolvedIdx = Math.max(0, Math.min(urls.length - 1, Number(node.previewIndex ?? 0)));
        }
    }
    previewIndex = resolvedIdx;
    url = urls[resolvedIdx] || url;
    const multi = urls.length > 1;
    const isVideoGen = node.type === 'video';
    const favorited = isOutputUrlFavorited(url);
    const histItem = generatorHistoryItems(node).find(x => x.url === url) || {url};
    const canSaveLibrary = url && !isMissingAssetUrl(url) && !isAudioUrl(url);
    const deleteOthersLabel = isVideoGen
        ? (en ? 'Delete other videos' : '删除其它视频')
        : (en ? 'Delete other images' : '删除其他图片');
    imageNodeMenu.innerHTML = `
        <button class="menu-btn" type="button" data-gen-preview="1"><i data-lucide="maximize-2" class="w-4 h-4"></i><span>${en ? 'Open preview' : '进入预览'}</span></button>
        ${multi ? `<button class="menu-btn" type="button" data-gen-set-primary="1"><i data-lucide="pin" class="w-4 h-4"></i><span>${en ? 'Set as primary' : '设为主图'}</span></button>` : ''}
        <button class="menu-btn" type="button" data-gen-favorite="1"><i data-lucide="star" class="w-4 h-4"></i><span>${favorited ? (en ? 'Remove favorite' : '取消收藏') : (en ? 'Save to favorites' : '保存到我的收藏')}</span></button>
        <button class="menu-btn" type="button" data-gen-duplicate="1"><i data-lucide="copy-plus" class="w-4 h-4"></i><span>${en ? 'Create copy' : '创建副本'}</span></button>
        ${!isVideoGen && url && !isMissingAssetUrl(url) ? `<button class="menu-btn" type="button" data-gen-copy-image="1"><i data-lucide="copy" class="w-4 h-4"></i><span>${en ? 'Copy image' : '复制图片'}</span></button>` : ''}
        <button class="menu-btn" type="button" data-gen-download-one="1"><i data-lucide="download" class="w-4 h-4"></i><span>${en ? 'Download' : '下载'}</span></button>
        ${canSaveLibrary ? `<button class="menu-btn" type="button" data-gen-save-library="1"><i data-lucide="folder-plus" class="w-4 h-4"></i><span>${en ? 'Save to library' : '保存到素材库'}</span></button>` : ''}
        ${isVideoGen ? '' : `<button class="menu-btn" type="button" data-gen-join-batch="1"><i data-lucide="images" class="w-4 h-4"></i><span>${en ? 'Add to image group' : '加入图片组'}</span></button>`}
        ${multi ? `<button class="menu-btn" type="button" data-gen-delete-others="1"><i data-lucide="trash-2" class="w-4 h-4"></i><span>${escapeHtml(deleteOthersLabel)}</span></button>` : ''}
        ${multi ? `<div class="menu-sep" aria-hidden="true"></div>` : ''}
        ${multi ? `<button class="menu-btn" type="button" data-gen-expand-all="1"><i data-lucide="layout-grid" class="w-4 h-4"></i><span>${en ? 'Expand all nodes' : '展开所有节点'}</span></button>` : ''}
        ${multi ? `<button class="menu-btn" type="button" data-gen-download-all="1"><i data-lucide="download" class="w-4 h-4"></i><span>${en ? 'Download all' : '下载全部'}</span></button>` : ''}
    `;
    placeImageNodeMenuNearPointer(clientX, clientY);
    const refreshAfter = () => {
        refreshNodes([node.id]);
        scheduleSave();
    };
    imageNodeMenu.querySelector('[data-gen-preview]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        openGeneratorHistoryLightbox(node, url);
    });
    imageNodeMenu.querySelector('[data-gen-set-primary]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        try { pushUndo(); } catch(_){ /* ignore */ }
        setGeneratorPrimaryByDisplaySwap(node, previewIndex, url);
        refreshDownstreamGenConsumers(node.id);
        setGenStageHistoryOpen(node, false);
        refreshAfter();
        syncImageGenDock();
        setStatus(en ? 'Set as primary' : '已设为主图');
    });
    imageNodeMenu.querySelector('[data-gen-favorite]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        void toggleFavoriteForUrl(url, histItem, node, null);
    });
    imageNodeMenu.querySelector('[data-gen-copy-image]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        void copyImageUrlToClipboard(url)
            .then(() => setStatus(en ? 'Image copied' : '已复制图片'))
            .catch(err => softAlert(err?.message || (en ? 'Copy failed' : '复制失败')));
    });
    imageNodeMenu.querySelector('[data-gen-download-one]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        downloadUrl(url, outputDownloadName(url)).catch(err => softAlert(err.message || tr('canvas.outputDownloadEmpty')));
    });
    imageNodeMenu.querySelector('[data-gen-save-library]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        void openAssetLibrarySaveModal(url, histItem?.name || outputImageName(url));
    });
    bindGenStageDuplicateMenuAction(nodeId);
    imageNodeMenu.querySelector('[data-gen-join-batch]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        startGenBatchPick(nodeId, url);
    });
    imageNodeMenu.querySelector('[data-gen-delete-others]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        try { pushUndo(); } catch(_){ /* ignore */ }
        if(deleteOtherGeneratorPreviews(node, url)){
            refreshAfter();
            syncImageGenDock();
            setStatus(isVideoGen
                ? (en ? 'Kept this video only' : '已删除其它视频')
                : (en ? 'Kept this image only' : '已删除其他图片'));
        } else {
            softAlert(isVideoGen
                ? (en ? 'Could not delete other videos' : '删除其它视频失败')
                : (en ? 'Could not delete other images' : '删除其他图片失败'));
        }
    });
    imageNodeMenu.querySelector('[data-gen-expand-all]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        expandGenStageResultsToGeneratorNodes(nodeId);
    });
    imageNodeMenu.querySelector('[data-gen-download-all]')?.addEventListener('click', e => {
        e.stopPropagation();
        closeImageNodeMenu();
        urls.forEach(u => {
            downloadUrl(u, outputDownloadName(u)).catch(err => softAlert(err.message || tr('canvas.outputDownloadEmpty')));
        });
    });
    refreshIcons(imageNodeMenu);
}
function buildExpandedGeneratorFromResult(source, url, histItem, x, y){
    const prompt = String(histItem?.prompt || source.prompt || '').trim();
    const model = String(histItem?.model || source.model || source.msCustomModel || '');
    return {
        id:uid('gen'),
        type:source.type,
        x,
        y,
        w:Number(source.w || 260),
        apiProvider:source.apiProvider || '',
        model:source.model || '',
        prompt,
        ratio:source.ratio || 'square',
        resolution:source.resolution || '1k',
        customRatio:source.customRatio || '',
        customSize:source.customSize || '',
        customRatioWidth:source.customRatioWidth || '',
        customRatioHeight:source.customRatioHeight || '',
        customWidth:source.customWidth || '',
        customHeight:source.customHeight || '',
        count:1,
        quality:source.quality,
        msgenModel:source.msgenModel,
        msRatio:source.msRatio,
        msResolution:source.msResolution,
        msCustomModel:source.msCustomModel,
        msCustomRatio:source.msCustomRatio,
        msCustomSize:source.msCustomSize,
        duration:source.duration,
        aspectRatio:source.aspectRatio,
        enhancePrompt:source.enhancePrompt,
        enableUpsample:source.enableUpsample,
        useFrameRoles:source.useFrameRoles,
        previewRoundUrls:[url],
        history:[{
            url,
            prompt,
            model,
            runMs:Number(histItem?.runMs || 0) || 0,
            viewed:true,
            createdAt:nowMs(),
        }],
        previewIndex:0,
        historyOpen:false,
        inputs:[],
        runStatus:'idle',
        running:false,
    };
}
/** 右键「展开所有节点」：拆成独立图片生成节点，上游扇出，移除源节点（图2；点选即图3控制台） */
function expandGenStageResultsToGeneratorNodes(sourceId){
    const source = nodes.find(n => n.id === sourceId);
    if(!source || !isGenConsoleNode(source)) return;
    const urls = generatorPreviewUrls(source);
    if(urls.length < 2){
        softAlert(langIsEn() ? 'Need at least 2 results to expand' : '至少两张结果才能展开');
        return;
    }
    try { pushUndo(); } catch(err) { console.warn('[infinite-canvas] undo snapshot failed', err); }
    const items = generatorHistoryItems(source);
    const baseW = Number(source.w || 260);
    const rowH = Math.round(baseW * 1.45) + 36;
    const startX = source.x;
    const startY = source.y;
    const incoming = connections.filter(c => c.to === source.id);
    const outgoing = connections.filter(c => c.from === source.id);
    const createdIds = [];
    urls.forEach((url, i) => {
        const histItem = items.find(x => x.url === url) || {url, prompt:source.prompt || ''};
        const child = buildExpandedGeneratorFromResult(
            source,
            url,
            histItem,
            startX,
            startY + i * rowH
        );
        nodes.push(child);
        incoming.forEach(c => {
            if(canConnect(c.from, child.id)){
                connections.push({id:uid('c'), from:c.from, to:child.id});
            }
        });
        createdIds.push(child.id);
    });
    const primaryUrl = urls[Math.max(0, Math.min(urls.length - 1, Number(source.previewIndex ?? urls.length - 1)))];
    const primaryChildId = createdIds[Math.max(0, urls.indexOf(primaryUrl))] || createdIds[0];
    outgoing.forEach(c => {
        if(primaryChildId && canConnect(primaryChildId, c.to)){
            connections.push({id:uid('c'), from:primaryChildId, to:c.to});
        }
    });
    purgeNodeFromGroups(source.id);
    try { destroyLTXEditor(source); } catch(_){ /* ignore */ }
    nodes = nodes.filter(n => n.id !== source.id);
    connections = connections.filter(c => c.from !== source.id && c.to !== source.id);
    selected.clear();
    if(primaryChildId) selected.add(primaryChildId);
    syncGeneratorInputs();
    commitStructureDomPatch({
        addedIds: createdIds,
        removedIds: [source.id],
        refreshIds: outgoing.map(c => c.to).filter(Boolean),
    });
    scheduleSave();
}
function genDockRatioOptions(node){
    const caps = generatorModelCaps(node?.model);
    const keys = caps.ratioKeys?.length ? caps.ratioKeys : GENERATOR_ALL_RATIO_KEYS;
    return keys.map(k => `<option value="${escapeAttr(k)}">${escapeHtml(genRatioShortLabel(k))}</option>`).join('');
}
function genRatioShortLabel(ratio){
    const r = String(ratio || '').trim();
    if(/^\d+:\d+$/.test(r)) return r;
    const map = {
        source: langIsEn() ? 'Auto' : '自适应',
        square: '1:1',
        story: '9:16',
        wide: '16:9',
        portrait43: '3:4',
        landscape43: '4:3',
        landscape: '3:2',
        portrait: '2:3',
        custom: langIsEn() ? 'Custom' : '自定义',
    };
    return map[r] || r || '1:1';
}
function genResShortLabel(resolution){
    const key = String(resolution || '1k').toLowerCase();
    if(key === 'custom') return langIsEn() ? 'Custom' : '自定义';
    return key.toUpperCase();
}
function genSizeSummaryText(node){
    const ratio = genRatioShortLabel(node?.ratio || 'square');
    const caps = generatorModelCaps(node?.model);
    if(!caps.resolutionKeys?.length) return ratio;
    return `${ratio} · ${genResShortLabel(node?.resolution || '1k')}`;
}
