/** App 壳层切走（非画布路由）时挂起：避免「选择画布」透过半透明封面闪一下 */
export function setInfiniteCanvasShellSuspended(suspended) {
  if(!canvasRoot) return;
  if(suspended){
    stopCanvasRemotePolling();
    canvasRoot.dataset.shellSuspended = '1';
    canvasRoot.dataset.shellActive = '0';
  } else {
    delete canvasRoot.dataset.shellSuspended;
    canvasRoot.dataset.shellActive = '1';
    rebindDomIfStale();
    if(board && !boardEventsWired) wireBoardEvents();
    requestAnimationFrame(() => {
      refreshInfiniteCanvasLayout();
    });
    if(canvas) startCanvasRemotePolling();
    else if(!trashMode && creatingCanvas) setCreateMode(false);
  }
}

export function disposeInfiniteCanvasEngine({ preserveEditor = false } = {}) {
  hideCustomTooltip();
  clearBoardPanListeners();
  pendingNodeDrag = null;
  endDrag();
  // HMR / 卸载：只清编辑态 chrome，不做视口动画（DOM 即将拆掉）
  try {
    cancelImageEditViewportAnim();
    if(imageEditViewportBackup){
      viewport.x = imageEditViewportBackup.x;
      viewport.y = imageEditViewportBackup.y;
      viewport.scale = imageEditViewportBackup.scale;
      imageEditViewportBackup = null;
    }
    imageEditFocusNodeId = '';
    forceClearImageEditChrome();
    try { closeTextNodeExpand(); } catch(_) {}
  } catch(_) {}
  try { flushLiveCanvasDraftPersist(); } catch(_) {}
  try { flushCanvasSaveKeepalive(); } catch(_) {}
  stopCanvasRemotePolling();
  if(outputTimer){
    clearInterval(outputTimer);
    outputTimer = null;
  }
  clearTimeout(saveTimer);
  saveTimer = null;
  clearTimeout(viewportSaveTimer);
  viewportSaveTimer = null;
  clearTimeout(remoteSyncTimer);
  remoteSyncTimer = null;
  disposers.forEach((d) => {
    try { d(); } catch (_) {}
  });
  disposers.length = 0;
  boardEventsWired = false;
  imageEditorUiWired = false;
  setSpacePanArmed(false);
  if (board) {
    board.style.cursor = '';
    board.onmousedown = null;
    board.onwheel = null;
    board.ondblclick = null;
    board.oncontextmenu = null;
    board.onmousemove = null;
    board.onmouseleave = null;
  }
  window.onmousemove = null;
  window.onmouseup = null;
  if(!preserveEditor){
    canvas = null;
    nodes = [];
    connections = [];
    selected.clear();
  }
  canvasRoot = null;
  mountedEngineRoot = null;
  board = null;
  world = null;
  nodesEl = null;
  linksEl = null;
  shell = null;
  minimapState = null;
  minimapRenderQueued = false;
  minimapNeedsFull = false;
}
